CREATE TABLE IF NOT EXISTS admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id text UNIQUE, email text NOT NULL UNIQUE, role text NOT NULL CHECK (role IN ('ADMIN','OPERATOR')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_request_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_request_id uuid NOT NULL REFERENCES purchase_requests(id) ON DELETE CASCADE, admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT, note text NOT NULL CHECK (length(trim(note)) > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE RESTRICT, admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT, note text NOT NULL CHECK (length(trim(note)) > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS inventory_adjustments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), variant_id uuid NOT NULL REFERENCES product_variants(id) ON DELETE RESTRICT, admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT, type text NOT NULL CHECK (type IN ('MANUAL_CORRECTION','RESTOCK','DAMAGE','RETURN')), quantity_delta integer NOT NULL CHECK (quantity_delta <> 0), reason text NOT NULL CHECK (length(trim(reason)) > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_activity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE RESTRICT, action text NOT NULL, entity_type text NOT NULL, entity_id uuid NULL, metadata_json jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS admin_sessions_expiry_idx ON admin_sessions(expires_at); CREATE INDEX IF NOT EXISTS purchase_request_notes_request_idx ON purchase_request_notes(purchase_request_id); CREATE INDEX IF NOT EXISTS order_notes_order_idx ON order_notes(order_id); CREATE INDEX IF NOT EXISTS inventory_adjustments_variant_idx ON inventory_adjustments(variant_id); CREATE INDEX IF NOT EXISTS admin_activity_created_idx ON admin_activity(created_at);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS carrier text NULL, ADD COLUMN IF NOT EXISTS tracking_number text NULL, ADD COLUMN IF NOT EXISTS tracking_url text NULL, ADD COLUMN IF NOT EXISTS shipped_at timestamptz NULL, ADD COLUMN IF NOT EXISTS review_resolved_at timestamptz NULL, ADD COLUMN IF NOT EXISTS review_resolved_by uuid NULL REFERENCES admin_users(id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS review_resolution_note text NULL;
CREATE UNIQUE INDEX IF NOT EXISTS purchase_request_one_order_idx ON orders(purchase_request_id) WHERE purchase_request_id IS NOT NULL;
